import{_ as a,o,c as n,a6 as r}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Administrar conexiones LIVE","description":"","frontmatter":{"title":"Administrar conexiones LIVE","docId":"user.live.connections","translationKey":"user.live.connections","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"37f7274550d3010051ab456da2a2091b650e5e7aaaf30756b6695435bcfc08c7","translationRevision":"0114d352743971a04daab4955a1ffc6c828b1f1f417e62656def1b292763e63b","order":10},"headers":[],"relativePath":"es/user/live/connections.md","filePath":"es/user/live/connections.md","lastUpdated":1794611623000}'),i={name:"es/user/live/connections.md"};function t(s,e,c,l,d,u){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="manage-live-connections" tabindex="-1">Administrar conexiones LIVE <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to &quot;Administrar conexiones LIVE {#manage-live-connections}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Conecta con un creador concreto, comprende la reconexión y configura los servidores de plugins por separado. Necesitas una <a href="./../installation.html">instalación de escritorio</a>, acceso a Internet y el identificador del creador. Consulta los <a href="./../requirements.html">requisitos</a> antes de investigar problemas del sistema operativo.</p><h2 id="connect-deliberately" tabindex="-1">Conectar con intención <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to &quot;Conectar con intención {#connect-deliberately}&quot;">​</a></h2><ol><li>Abre <strong>Connections</strong>. Introduce el identificador, con o sin <code>@</code>; el nombre visible no es el mismo dato.</li><li>Comienza con <strong>Use Cookie</strong> desactivado. Si TikTok exige una sesión autorizada, actívalo e introduce la cookie únicamente en el campo oculto. Las cookies permanecen en memoria; no las pegues en diagnósticos ni en ajustes de Cloud.</li><li>Deja <strong>Monitor and auto-connect</strong> desactivado para un intento directo y pulsa <strong>Connect</strong>. Lee el estado y cualquier error antes de repetirlo.</li><li>Comprueba en el <a href="./feed.html">feed LIVE</a> que aparecen el creador correcto y un evento nuevo. Una sala conectada pero tranquila puede no mostrar actividad.</li><li>Usa <strong>Reconnect</strong> para el mismo creador o <strong>Disconnect</strong> antes de cambiarlo. Durante un intento en curso, <strong>Cancel</strong> permite detenerlo.</li></ol><p>Tras una conexión directa satisfactoria, activa la supervisión para esperar a que el creador inicie un LIVE. Esperar y comprobar son estados distintos de estar conectado. Detén la supervisión antes de editar un identificador bloqueado. Seleccionar un creador reciente inicia la conexión; no se limita a rellenar el campo.</p><p>El explorador ofrece salas descubiertas, pero sus resultados pueden caducar. Actualízalos antes de asumir que siguen disponibles. Los servidores de plugins del panel inferior configuran servicios propios; conectar un plugin no autentica TikTok ni Cloud.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Están disponibles las conexiones directas, la supervisión y los controles de plugins. Reconectar al mismo creador conserva el contexto del feed; cambiarlo inicia otro. El acceso real a TikTok depende de la sala y la sesión externas; una prueba local satisfactoria no lo garantiza.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si la sala está desconectada, confirma que el creador está en directo. Ante errores de sesión o límites de solicitudes, respeta la condición de reintento indicada. Reconectar repetidamente no renueva la autenticación. Consulta <a href="./../preferences/troubleshooting.html">solución de problemas</a> para registrar el componente y la hora sin revelar credenciales.</p>',11)])])}const f=a(i,[["render",t]]);export{m as __pageData,f as default};
